(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0009.js"] = [{"id":"glyph-kai-7a84","script":"kai","character":"窄","reading":"zhǎi","description":"zhǎi：(1)横的距离小，与宽”相对狭～。～小。冤家路～。\n(2)心胸不开朗，气量小心～。\n(3)生活不富裕日子过得挺～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窄"},{"id":"glyph-kai-7a8d","script":"kai","character":"窍","reading":"qiào","description":"指耳鼻目口等器官之孔\n比喻事情的关键或要害\n⒉〈喻〉事情的关键或巧妙的方法～门。诀～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窍"},{"id":"glyph-kai-7a91","script":"kai","character":"窑","reading":"yáo","description":"yáo：(1)烧砖、瓦、陶瓷器的构筑物砖～。瓷～。\n(2)为采煤而凿的洞煤～。\n(3)在坡上特为住人挖的洞～洞。～葬。\n(4)旧时称妓院～子。～姐（妓女）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窑"},{"id":"glyph-kai-7a92","script":"kai","character":"窒","reading":"zhì","description":"zhì：阻塞不通～息。～塞。～闷。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窒"},{"id":"glyph-kai-7a96","script":"kai","character":"窖","reading":"jiào","description":"jiào：(1)收藏东西的地洞或坑～穴。～子。地～。\n(2)把东西藏在地窖里～藏。～白菜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窖"},{"id":"glyph-kai-7a97","script":"kai","character":"窗","reading":"chuāng","description":"chuāng：房屋通风透气的装置～子。～户。～口。～友（即同学）。～花。～台。～纱。～帘。～幔。～明几净。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窗"},{"id":"glyph-kai-7a98","script":"kai","character":"窘","reading":"jiǒng","description":"jiǒng：(1)穷困～厄。～乏。～苦。～困。～迫。～促。～急。\n(2)难住，使为难～况。～态。～相。～境。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窘"},{"id":"glyph-kai-7a9c","script":"kai","character":"窜","reading":"cuàn","description":"奔逃\n放逐\n删改\n羼杂;混入\n骚扰\n②放逐；驱逐；贬官。\n【窜红】走红。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窜"},{"id":"glyph-kai-7a9d","script":"kai","character":"窝","reading":"wō","description":"鸟兽昆虫的巢穴\n巢穴,窟,尤指用作隐藏或避难用的洞穴\n身体表面的天然凹隐\n借指人的安身处\n指人或物体所在或所占的地方\n物成团或簇。亦指事物集中处\n⒈鸟兽昆虫等的巢穴燕～。狗～。蜂～儿。\n⒉凹陷的地方心～。酒～儿。\n⒊藏匿犯法的人或物～主。～赃。～贼。～藏。\n⒋坏人群居的地方匪～。\n⒌弄弯，曲折将铁棍～个钩。\n⒍郁积，不发作或不发挥～ 火。～气。\n⒎量词她养了三～蜂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窝"},{"id":"glyph-kai-7a9f","script":"kai","character":"窟","reading":"kū","description":"kū：(1)洞穴石～。狡兔三～。～窿。\n(2)人聚集的地方，多指歹徒聚集之所匪～。魔～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窟"},{"id":"glyph-kai-7aa5","script":"kai","character":"窥","reading":"kuī","description":"暗中察看。亦泛指观看\n观察,侦探\n伺机图\n窥kuǐ 1.半步。言一举足即到。 2.引申为到。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窥"},{"id":"glyph-kai-7abf","script":"kai","character":"窿","reading":"lóng","description":"lóng：煤矿坑道～工。清理废～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窿"},{"id":"glyph-kai-7acb","script":"kai","character":"立","reading":"lì","description":"lì：(1)站，引申为竖起来～正。～柜。～足（ａ．站得往脚；ｂ．处于某种立场）。～场。屹～。顶天～地。\n(2)做出，定出建～。设～。树～。～意。～此存照。\n(3)存在，生存自～。独～。势不两～。\n(4)马上，即刻～时。～刻。～等。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-立"},{"id":"glyph-kai-7ad6","script":"kai","character":"竖","reading":"shù","description":"纵。与横”相反\n短小\n童仆\n⒈立，直立～立。～栅列营。将竹竿～起来。\n⒉上下或前后的方向，跟\"横\"相对～排。～着砌道墙。\n⒊直『字笔形之一，从上往下写\"干\"字是二横一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竖"},{"id":"glyph-kai-7ad9","script":"kai","character":"站","reading":"zhàn","description":"zhàn：(1)立，久立～立。～岗。～起来。\n(2)停～住。～住脚。\n(3)中途停留转运的地方驿～。～台。火车～。起点～。\n(4)分支办事单位保健～。防疫～。供应～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-站"},{"id":"glyph-kai-7ade","script":"kai","character":"竞","reading":"jìng","description":"争辩\n⒈争逐，比赛，互相争胜～走。～赛。～争。\n⒉强劲南风不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竞"},{"id":"glyph-kai-7adf","script":"kai","character":"竟","reading":"jìng","description":"jìng：(1)终了，完毕继承先烈未～的事业。\n(2)到底，终于毕～。有志者事～成。\n(3)整，从头到尾～日。～夜。\n(4)居然，表示出乎意料～然。～至（竟然至于）。～自（竟然）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竟"},{"id":"glyph-kai-7ae0","script":"kai","character":"章","reading":"zhāng","description":"zhāng：(1)歌曲诗文的段落～节。～句。乐～。～回体。顺理成～。断～取义。\n(2)条目，规程～程。～法。简～。党～。约法三～。\n(3)修理杂乱无～。\n(4)花纹，文采黑质而白～。\n(5)戳记图～。盖～。\n(6)佩带的身上的标志袖～。领～。徽～。像～。\n(7)奏本奏～。本～。\n(8)古同彰”，彰明。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-章"},{"id":"glyph-kai-7ae3","script":"kai","character":"竣","reading":"jùn","description":"jùn：事情完毕～事。～工。完～。大功告～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竣"},{"id":"glyph-kai-7ae5","script":"kai","character":"童","reading":"tóng","description":"tóng：(1)小孩子儿～。～工。～谣。～话。～心。～趣。～真。\n(2)旧时未成年的仆人书～儿。\n(3)没有结婚的～男。～女。～贞。\n(4)未长成的～牛（没长角的小牛）。\n(5)秃～山。头～（喻人秃顶，如～～齿豁”）。\n(6)古同瞳”，瞳孔。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-童"},{"id":"glyph-kai-7aed","script":"kai","character":"竭","reading":"jié","description":"jié：尽，用尽～诚。～尽。～力。～泽而渔。枯～。衰～。声嘶力～。用之不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竭"},{"id":"glyph-kai-7aef","script":"kai","character":"端","reading":"duān","description":"duān：(1)正，不歪斜～正（ａ．事物不歪斜；ｂ．正派，正确；ｃ．使端正）。～丽。～然。～庄。～秀。～静。～坐。\n(2)正派，正直～方。～直。～重（zhòng）。品行不～。\n(3)事物的一头～的（dì）（ａ．事情的经过，底细；ｂ．的确，果然；ｃ．究竟。均亦称端底”）。～倪。～详。事～。争～。\n(4)用手很平正地拿～盆。～碗。～茶。把问题～出来说清楚。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-端"},{"id":"glyph-kai-7af9","script":"kai","character":"竹","reading":"zhú","description":"茎有节的植物，常见于诗词与绘画。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-7aff","script":"kai","character":"竿","reading":"gān","description":"gān：(1)竹子的主干竹～。立～见影。揭～而起。\n(2)特指钓鱼竿”垂～。投～。～钓。\n(3)古代指竹简～牍（书信）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-竿"},{"id":"glyph-kai-7b0b","script":"kai","character":"笋","reading":"sǔn","description":"sǔn：(1)竹子初从土里长出的嫩茎、芽，又称竹笋”，可以做菜吃。可食用者主要有毛竹笋”、慈竹笋”、麻竹笋”等。\n(2)竹子的青皮～席（用竹青编成的席子）。\n(3)古同榫”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笋"},{"id":"glyph-kai-7b11","script":"kai","character":"笑","reading":"xiào","description":"xiào：(1)露出愉快的表情，发出欢喜的声音～容。～颜。～眯眯。谈～风生。\n(2)讥嘲～柄。～话。～谈。贻～大方。嘲～。见～。耻～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笑"},{"id":"glyph-kai-7b14","script":"kai","character":"笔","reading":"bǐ","description":"指字画诗文等以笔书写绘制而成的作\n①写字画图的用具钢～、蜡～、粉～。\n③用笔写出代～。\n④笔画'二'字有两～。\n⑤量词一～帐、一～好字。\n【笔触】书画、文学作品等的笔法，格调锋利的～。\n【笔调】文章风格～清新。\n【笔端】写作、写字、绘画时的运笔以及所表现的意境奇光异景尽收～。\n【笔法】写字、画画、作文的技巧或特色这篇小说的～很新颖。\n【笔锋】\n①笔尖。\n②书画的笔势；文章的气势。\n【笔供】用笔写出来的供词。与'口供'相对。\n【笔画笔顺检字法】汉字字典查阅检索方法之一。要求根据笔画的多少和笔顺的先后来查检。\n【笔记文】文体的一种。以随笔记录为主，多由分条的短篇汇集而成。\n【笔力】写字、画画或做文章所表现出的功力～刚劲。\n【笔路】\n①笔法。\n②写作的思路这篇文章～奇特。\n【笔势】\n①写字、画画用笔的风格。\n②文章的气势。\n【笔削】古时在竹简、木简上写字，要删改得用刀刮去，称'削'◇来用做请人修改文章的敬辞。笔记录。削删改。\n【笔意】书画或诗文中所表现出的作者的意境。写字、绘画时运笔的精心构思以及所表现的风格、功力。也指诗文的意境。\n【笔札】札是古时写字用的小木片，后来用笔札指纸笔，又转指写的文章。\n【笔战】用文章来进行辩论，打官司，与'舌战'相对。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笔"},{"id":"glyph-kai-7b19","script":"kai","character":"笙","reading":"shēng","description":"shēng：管乐器名，一般用十三根长短不同的竹管制成，吹奏～歌。芦～。～管乐（yuè）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笙"},{"id":"glyph-kai-7b1b","script":"kai","character":"笛","reading":"dí","description":"dí：(1)管乐器名，通常是竹制的，有八孔，横着吹奏～子。长～。短～。～膜。\n(2)响声尖锐的发音器汽～。警～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笛"},{"id":"glyph-kai-7b26","script":"kai","character":"符","reading":"fú","description":"fú：(1)古代朝廷传达命令或征调兵将用的凭证虎～。～信。～节。\n(2)代表事物的标记、记号～号。音～。\n(3)相合～合。言行相～。\n(4)道士画的驱使鬼神的图形或线条～咒。护身～。\n(5)古代称祥瑞的征兆～瑞。～应（yìng）（指天降符瑞”，与人事相应）。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-符"},{"id":"glyph-kai-7b28","script":"kai","character":"笨","reading":"bèn","description":"bèn：(1)不聪明～人。～拙。～伯（ａ．傻瓜，愚蠢的人；ｂ．肥大的人）。愚～。\n(2)不灵巧嘴～。～口拙舌。～鸟先飞。\n(3)粗重，费力气的～重。～活。粗～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笨"},{"id":"glyph-kai-7b2c","script":"kai","character":"第","reading":"dì","description":"dì：(1)次序～一。次～。等～。\n(2)科举考试及格的等次科～。及～。落～。\n(3)封建社会官僚贵族的大宅子宅～。府～。门～。进士～。\n(4)但运动有益于健康，～不宜过于剧烈。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-第"},{"id":"glyph-kai-7b3c","script":"kai","character":"笼","reading":"lóng","description":"用竹片编成的盛物的器具\n桂枝为笼钩。\n饲养鸟、虫、家禽等的笼子\n⒉较大的箱子箱～。\n⒈用竹篾、木条或塑料等制做的盛物器或罩物器筷～。灯～。\n⒉养鸟、兽等的器具鸡～。鸟～子。蝈蝈～。\n⒊囚禁犯人的刑具囚～。\n⒋有盖用以蒸东西的器具蒸～。～屉。\n⒌将手放在袖筒里～着手。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-笼"},{"id":"glyph-kai-7b49","script":"kai","character":"等","reading":"děng","description":"děng：(1)古代指顿齐竹简（书）。\n(2)数量、程度相同，或地位一般高相～。平～。～于。～同。～值。～量齐观。\n(3)表示数量或程度的级别～级。～次。～第。～而下之。\n(4)特指台阶的级。\n(5)种，类这～事。\n(6)表示同一辈份的多数人我～。尔～。\n(7)表示列举未尽，或用于列举煞尾北京、上海～地。\n(8)候，待～候。～待。\n(9)待到～我写完。\n(10)同戥”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-等"},{"id":"glyph-kai-7b4b","script":"kai","character":"筋","reading":"jīn","description":"jīn：(1)肌肉的俗称～力。～肉。～疲力尽。\n(2)肌腱或附着在骨头上的韧带～骨。～道（道”读轻声）。蹄～。\n(3)可见的皮下静脉的俗称～络。～脉。青～暴露。\n(4)像筋的东西钢～。橡皮～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筋"},{"id":"glyph-kai-7b4f","script":"kai","character":"筏","reading":"fá","description":"fá：用竹、木等平摆着编扎成的水上交通工具～子。竹～。皮～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筏"},{"id":"glyph-kai-7b50","script":"kai","character":"筐","reading":"kuāng","description":"kuāng：竹子或柳条等编成的盛东西的器具～子。土～。抬～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筐"},{"id":"glyph-kai-7b51","script":"kai","character":"筑","reading":"zhù","description":"捣土使坚实\n筑zhú 1.古弦乐器名。有五弦﹑十三弦﹑二十一弦三种说法。其形似筝，颈细而肩圆，弦下设柱。演奏时，左手按弦的一端，右手执竹尺击弦发音。战国时已有流行。 2.拾\n。 3.贵州省贵阳市的简称。明代称为贵筑司﹑贵筑乡，清代改为贵筑县◇因省称筑。\n筑zhù 1.捣土的杵。 2.捣土使坚实。 3.修建，建造。 4.居室;建筑物。 5.打，击。 6.填塞;装填。 7.拾取。 8.量名。 9.通\"祝\"。切断。 10.通\"妯\"。参见\"\n筑娌\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筑"},{"id":"glyph-kai-7b52","script":"kai","character":"筒","reading":"tǒng","description":"tǒng：(1)粗大的竹管。\n(2)较粗的中空而高的器物烟～。邮～。笔～。\n(3)衣服等的筒状部分袖～儿。靴～。～裙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筒"},{"id":"glyph-kai-7b54","script":"kai","character":"答","reading":"dá；dā","description":"dá：(1)回话，回复回～。对～。～辩。～复。～案。对～如流。\n(2)受了别人的好处，还（huán）报别人报～。～报。\n问；\ndā：义同（一），用于答应”答理”等词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-答"},{"id":"glyph-kai-7b56","script":"kai","character":"策","reading":"cè","description":"cè：(1)古代的一种马鞭子，头上有尖刺。\n(2)鞭打～马。鞭～。\n(3)激励，促进～动。～勉。\n(4)古代称连编好的竹简简～。\n(5)古代帝王对臣下封土、授爵或免官～命。～免。～封。\n(6)古代科举考试的一种文体～论。～问。\n(7)杖～杖。\n(8)中国数学上曾经用过的一种计算工具，形状与筹”相似。\n(9)计谋，主意，办法上～。献～。决～。政～。～划。束手无～。\n(10)书法用字名称，指仰横。\n(11)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-策"},{"id":"glyph-kai-7b5b","script":"kai","character":"筛","reading":"shāi","description":"用筛子过物\n斟酒\n击,敲\n⒉用筛子过漏东西～米。～沙石。\n⒊敲击～锣。\n⒋斟酒或将酒弄热～酒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筛"},{"id":"glyph-kai-7b5d","script":"kai","character":"筝","reading":"zhēng","description":"zhēng：弦乐器，木制长形。古代十三或十六根弦，现为二十五根弦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筝"},{"id":"glyph-kai-7b77","script":"kai","character":"筷","reading":"kuài","description":"kuài：夹饭或其他东西用的一对细棍儿（亦称箸”）～子。竹～。牙～。碗～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筷"},{"id":"glyph-kai-7b79","script":"kai","character":"筹","reading":"chóu","description":"壶矢。古代投壶用的签子,形如箭筩\n签筹;算筹\n算计\n策划\n①计数用具竹～。\n②谋划；筹划；计划～款、统～。\n【筹安会】袁世凯复辟帝制的御用团体。1915年8月由杨度、孙毓筠、严复、李燮和、胡瑛、刘师培等所谓'六君子'在北京发起成立。该会名义上以'研究君主、民主国体二者\n孰适于中国'为宗旨，实际公开进行复辟帝制活动。\n【筹划】想办法；定计划～工作。\n【筹算法】〈数〉我国古代用竹制的算筹记数并进行加、减、乘、除、开方等运算的方法。始于春秋时期，到明代被珠算代替。\n⒈计数的用具～码。\n⒉谋划，计划，计谋～备。熟～。统～安排。运～帷幄。一～莫展。\n⒊想办法收集～款。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-筹"},{"id":"glyph-kai-7b7e","script":"kai","character":"签","reading":"qiān","description":"用简单的文字拟具意见\n粗粗地缝合起来\n引,导引\n下令征调\n刺;插\n旧时官府交给差役拘捕犯人的片状凭证,多用竹、木做成\n⒈亲笔署名或画上符号～名。～押。\n⒉简要的写出重点或意见～注。\n⒊旧时官府拘人的凭证朱～。火～。\n⒋用竹木等做成的细条或片状物牙～子。竹～儿。\n⒌用作标志的片条标～儿。书～。\n⒍迷信或赌博使用的片条求～祈神自欺欺人。\n⒎粗粗地缝合起来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-签"},{"id":"glyph-kai-7b80","script":"kai","character":"简","reading":"jiǎn","description":"⒈不复杂，不烦琐，跟\"繁\"相对～单些。太～陋。～化。～明扼要。精兵～政。\n⒉轻忽，怠慢～慢。\n⒊盐，选择～拔。～选。\n⒋〈古〉用来写字的竹片或木片竹～。木～。〈引〉书信书～。来～。\n②〈方〉作\"索性\"讲天黑，雨又大，你～直别回去了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-简"},{"id":"glyph-kai-7b95","script":"kai","character":"箕","reading":"jī","description":"jī：(1)用竹篾、柳条或铁皮等制成的扬去糠麸或清除垃圾的器具（通常称簸箕”）～帚。\n(2)簸箕形的指纹，不成圆形斗（dǒu）～。\n(3)星名，二十八宿之一。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箕"},{"id":"glyph-kai-7b97","script":"kai","character":"算","reading":"suàn","description":"suàn：核计，计数～草。～盘。～式。～账。～术。～计（ａ．算数目；ｂ．考虑；ｃ．估计；ｄ．暗中某划损害别人。计”均读轻声）。清～。预～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-算"},{"id":"glyph-kai-7ba1","script":"kai","character":"管","reading":"guǎn","description":"guǎn：(1)吹奏的乐器～乐器。～弦乐。\n(2)圆而细长中空的东西～道。～线。～见（谦辞，浅陋的见识）。～窥蠡测（从竹管里看天，用瓢量海水，喻眼光狭窄，见识短浅）。～中窥豹。气～。血～。针～。双～齐下。\n(3)形状像管的电子器件电子～。晶体～。\n(4)负责，经理～理。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-管"},{"id":"glyph-kai-7ba9","script":"kai","character":"箩","reading":"luó","description":"箩筛\n量词\n用箩筛或滤","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箩"},{"id":"glyph-kai-7bab","script":"kai","character":"箫","reading":"xiāo","description":"箫xiǎo 1.小竹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箫"},{"id":"glyph-kai-7bad","script":"kai","character":"箭","reading":"jiàn","description":"jiàn：(1)用弓发射到远处的兵器弓～。～镞。～头。～在弦上（喻事情已经到了不得不做或话已经到了不得不说的地步）。\n(2)箭能射到的距离一～之遥。～步。\n(3)形容急切、迅速归心似～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箭"},{"id":"glyph-kai-7bb1","script":"kai","character":"箱","reading":"xiāng","description":"xiāng：(1)收藏衣物的方形器具，通常是上面有盖扣住～子。衣～。书～。药～。\n(2)像箱子的器具冰～。风～。信～。集装～。\n(3)同厢”⑤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-箱"},{"id":"glyph-kai-7bc7","script":"kai","character":"篇","reading":"piān","description":"piān：(1)首尾完成的文章或诗词～章。诗～。～目。～什（shí）（《诗经》中的雅”和颂”以十篇为一什”，所以诗章亦称篇什”）。～幅。长～大论。千～一律。\n(2)量词，指文章、纸张、书页一～论文。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篇"},{"id":"glyph-kai-7bd3","script":"kai","character":"篓","reading":"lǒu","description":"用竹、藤、柳条等编成的盛物器具，如鱼篓、背篓。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-7be1","script":"kai","character":"篡","reading":"cuàn","description":"cuàn：(1)封建时代特指臣子夺取君位故得肆其奸慝，以成～盗之祸”。～位。\n(2)泛指夺取大长公主执囚青，欲杀之，其友公孙敖与壮士往～之”。～夺。～党。～国。～权。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篡"},{"id":"glyph-kai-7bee","script":"kai","character":"篮","reading":"lán","description":"篮球架上供投球用的带网的铁圈\n竹轿\n⒈用竹、藤、柳条、塑料带等编成的上有提梁的盛物器竹～子。提～买菜。\n⒉指一种体育用品及体育活动～球。～架。～网。投～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篮"},{"id":"glyph-kai-7bf1","script":"kai","character":"篱","reading":"lí","description":"笊篱","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篱"},{"id":"glyph-kai-7bf7","script":"kai","character":"篷","reading":"péng","description":"péng：(1)遮蔽风雨和阳光的东西，用竹篾、苇席、布等做成～子。～布。车～。帐～。\n(2)特指船帆扯起～来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-篷"},{"id":"glyph-kai-7c07","script":"kai","character":"簇","reading":"cù","description":"cù：(1)聚集，丛凑，或丛聚成的堆或团～拥。～聚。～生。～居。花团锦～。\n(2)量词，用于聚集成团的东西一～鲜花。\n〔～新〕极新，常用来形容衣服。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-簇"},{"id":"glyph-kai-7c27","script":"kai","character":"簧","reading":"huáng","description":"huáng：(1)乐器里用金属或其他材料制成的发声薄片～片。笙～。双～管。巧舌如～。\n(2)器物里有弹力的机件弹（tán）～。锁～。\n〔双～〕ａ．曲艺的一种；ｂ．喻一方出面，一方背后操纵的活动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-簧"},{"id":"glyph-kai-7c38","script":"kai","character":"簸","reading":"bò；bǒ","description":"bò：〔～箕〕ａ．扬糠除秽、清理垃圾的器具，用竹篾、柳条或铁皮制成，三面有边沿，一面敞口；ｂ．簸箕形的指纹（箕”均读轻声）。\nbǒ：(1)用簸箕颠动米粮，扬去糠秕和灰尘～谷。\n(2)颠动摇晃颠～。～荡。～动。～弄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-簸"},{"id":"glyph-kai-7c3f","script":"kai","character":"簿","reading":"bù；bó","description":"bù：(1)本子，册籍～册。～记。～籍。～录。\n(2)古代称公文、案卷对～公堂。\n(3)古代的仪仗侍从～伍。卤～（古代帝王、后妃、王公大臣外出时的仪仗队。次序排列严格并明文著之于簿籍）。\n(4)笏。\nbó：古同箔”，养蚕席。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-簿"},{"id":"glyph-kai-7c4d","script":"kai","character":"籍","reading":"jí","description":"jí：(1)书，书册古～。书～。经～。典～。\n(2)登记隶属关系的簿册；隶属关系～贯。户～。国～。学～。\n(3)登记～没（mò）。～吏民。\n(4)征收～田。\n(5)古代各种捐税的统称。\n〔～～〕ａ．形容纷扰很大；ｂ．形容名声很大；ｃ．形容纵横交错的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-籍"},{"id":"glyph-kai-7c73","script":"kai","character":"米","reading":"mǐ","description":"mǐ：(1)谷类或其他植物的子实去了皮的名称小～。大～。稻～。～珠薪桂（米像珍珠；柴像桂木，形容物价昂贵，生活困难）。\n(2)国际长度单位（旧称公尺”米突”），一米等于三市尺。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-米"},{"id":"glyph-kai-7c7b","script":"kai","character":"类","reading":"lèi","description":"亦类此耳。\n⒈种，具有共同特征事物的综合同～。种～。分门别～。物伤其～。\n⒉似，像画虎～狗。刻鹄～鹜。\n⒊大抵，大致～多如斯。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-类"},{"id":"glyph-kai-7c7d","script":"kai","character":"籽","reading":"zǐ","description":"zǐ：某些植物所结的种子～实。～种（zhǒng）。瓜～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-籽"},{"id":"glyph-kai-7c89","script":"kai","character":"粉","reading":"fěn","description":"fěn：(1)细末儿～末。～剂。～尘。米～。花～。药～。漂白～。\n(2)特指化装用的粉末香～。～墨登场。～黛。扑～。～霜。\n(3)用涂料抹刷～刷。～饰。\n(4)使破碎，成为粉末～碎。～身碎骨。\n(5)白色的或带粉末的～墙。～蝶。～连纸。～笔。\n(6)用豆粉或别的粉做成的食品～丝。凉～。～皮。～芡（qiàn）。米～肉。\n(7)浅红色～色。～花。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粉"},{"id":"glyph-kai-7c92","script":"kai","character":"粒","reading":"lì","description":"lì：(1)成颗的东西，细小的固体米～。盐～。颗～。～子（ａ．成果的、细小的东西，子”读轻声；ｂ．指基本粒子”，物理学上指构成物体的最简单的物质）。\n(2)量词，多指颗粒状的东西一～米。一～珍珠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粒"},{"id":"glyph-kai-7c97","script":"kai","character":"粗","reading":"cū","description":"cū：(1)疏忽，不周密～心。～疏。～略。～率（shuài）。\n(2)不精致，工料毛糙～糙。～劣。～料。～纸。～粮。～制滥造。去～取精。\n(3)长条东西直径大的～大。～壮。～重。～实。～线条（ａ．指毛道粗的线条ｂ．喻粗率的性格、作风，亦喻文章的粗略的构思）。～枝大叶。\n(4)颗粒大的～沙子。\n(5)声音低而大～哑。～声～气。\n(6)鲁莽～鲁。～暴。～野。～犷。～俗。～笨。～人。～手～脚。\n(7)略微～略。～具规模。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粗"},{"id":"glyph-kai-7c98","script":"kai","character":"粘","reading":"zhān","description":"zhān：(1)东西互相附着连结在一起糖～牙。\n(2)用胶或糨糊把一种东西胶合在另一种东西上～贴。～连。～接。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粘"},{"id":"glyph-kai-7c9f","script":"kai","character":"粟","reading":"sù","description":"sù：(1)一年生草本植物，子实为圆形或椭圆小粒。北方通称谷子”，去皮后称小米”～子。沧海一～。\n(2)古代泛称谷类重（zhòng）农贵～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粟"},{"id":"glyph-kai-7ca4","script":"kai","character":"粤","reading":"yuè","description":"yuè：(1)中国广东省的别称～语。～剧。\n(2)古同聿”、越”、曰”，文言助词，用于句首或句中。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粤"},{"id":"glyph-kai-7ca5","script":"kai","character":"粥","reading":"zhōu；yù","description":"zhōu：(1)用米面等食物煮成的半流质食品小米～。\n(2)像粥的东西泥～。乱成一锅～。\nyù：(1)古同育”，生养。\n(2)古同鬻”，卖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粥"},{"id":"glyph-kai-7caa","script":"kai","character":"粪","reading":"fèn","description":"施肥\n屎,粪便\n⒈屎，大便～便。\n⒉施肥～地。～田。\n⒊扫除～除。\n【粪土】粪便和泥土。〈喻〉不值钱的东西，含有蔑视～土当年万户侯。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粪"},{"id":"glyph-kai-7cae","script":"kai","character":"粮","reading":"liáng","description":"桂馥曰谷也者,非古训。紌乃行者之干食。”\n多载资粮。\n引申指谷类;粮食\n⒈可吃的谷类、豆类等～食。干～。杂～。军～。民有余～。\n⒉农业税踊跃交公～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粮"},{"id":"glyph-kai-7cb1","script":"kai","character":"粱","reading":"liáng","description":"liáng：(1)粟的优良品种的总称一枕黄～。\n(2)精美的主食膏～（泛指美味的饭菜，如～～子弟”，旧时指达官贵人家的子弟）。～糗（粱制的干粮）。～肉。\n〔高～〕一年生草本植物，子实红褐色，可食，亦可酿酒、制淀粉。杆可用来编席、造纸等。亦称蜀黍”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粱"},{"id":"glyph-kai-7cb9","script":"kai","character":"粹","reading":"cuì","description":"cuì：(1)纯一，不杂纯～。～白。～而不杂。\n(2)精华国～（一国文化的精华）。文～。精～。\n(3)古同萃”，齐全，集聚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-粹"},{"id":"glyph-kai-7cbe","script":"kai","character":"精","reading":"jīng","description":"jīng：(1)上好的白米食不厌～”。\n(2)细密的，与粗”相对～密。～细。～确。～制。～读。～选。～心。～研。～雕细镂。\n(3)聪明，思想周密～悍。～敏。～明。\n(4)物质中最纯粹的部分，提炼出来的东西～华。～英。～神（ａ．指人主观世界，包括意识、思维活动和一般心理状态；ｂ．内容实质，主要的意义；ｃ．指人表现出来的活力）。\n(5)人表现出来的活力、生气～力。聚～会神。无～打采。\n(6)专一，深入～诚。～忠。～炼。～湛。～严。\n(7)雄性动物体内的生殖物质～子。\n(8)很、极～湿。～瘦。～光。\n(9)完美，最好～美。～妙。～益求～。\n(10)明朗，清明天～而见景星”。\n(11)神话传说中的妖怪～灵（ａ．鬼怪；ｂ．机灵）。妖～。\n(12)古同菁”，花。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-精"},{"id":"glyph-kai-7cca","script":"kai","character":"糊","reading":"hú；hū；hù","description":"hū：涂抹或粘合使封闭起来～了一层泥。\nhú：(1)粘合，涂附裱～。～墙。～窗户。\n(2)粥类～口。\n(3)同煳”。\n〔～涂〕ａ．不明事理；认识凝混乱，如他太～～了”；ｂ．内容混乱的，如～～账”。\nhù：(1)像粥一样的食物面～。辣椒～。\n(2)欺骗，蒙混，敷衍～弄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糊"},{"id":"glyph-kai-7cd5","script":"kai","character":"糕","reading":"gāo","description":"gāo：用米粉或面粉搀和其他材料蒸制或烘烤而成的食品年～。蛋～。绿豆～。～点。～饼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糕"},{"id":"glyph-kai-7cd6","script":"kai","character":"糖","reading":"táng","description":"táng：(1)从甘蔗、甜菜、米、麦等提制出来的甜的物质白～§～。冰～。～浆。～稀。～膏。～瓜儿。～房（旧时制糖的作坊。亦称糖寮”、榨寮”）。～衣。\n(2)碳水化合物，有机化合物的一类，分为单糖”、双糖”三种，是人体内产生热能的主要物质～元。～尿病（因人体内胰岛素分泌不足所引起。是一种以体内糖代谢紊乱、血糖增高为主的慢性疾病）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糖"},{"id":"glyph-kai-7cd9","script":"kai","character":"糙","reading":"cāo","description":"cāo：(1)米脱壳而未舂的状态～米。\n(2)不细致，不光滑粗～。毛～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糙"},{"id":"glyph-kai-7cdf","script":"kai","character":"糟","reading":"zāo","description":"zāo：(1)做酒剩下的渣子酒～。～粕（亦喻无价值的东西）。～蛋。～糠之妻（指贫穷时共患难的妻子）。\n(2)腐朽，腐烂～烂。～朽。\n(3)坏事情办～了。～糕。\n(4)作践，损害～蹋。～践（践”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糟"},{"id":"glyph-kai-7ce0","script":"kai","character":"糠","reading":"kāng","description":"kāng：(1)稻、麦、谷子等的子实所脱落的壳或皮米～。糟～。～秕。～醛（有机化合物，是制造塑料、合成纤维、合成橡胶、药物等的原料）。\n(2)萝卜等因失掉水分而中心呈蜂窝状。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糠"},{"id":"glyph-kai-7cef","script":"kai","character":"糯","reading":"nuò","description":"nuò：稻的一种，米黏性大～稻。～米（亦称江米”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-糯"},{"id":"glyph-kai-7cfb","script":"kai","character":"系","reading":"xì；ji","description":"拴;系结\n约束;羁绊\n拘囚\n留意;挂念\n牵涉;关连\n⒈结，缚，扣～鞋带。\n⒉见xì。\n⒈有联属、有条理的～统。水～。世～。派～。一～列。\n⒉高等学校中按学科设置的教学单位哲学～。数学～。生物～。\n⒊是确～真情。\n⒋关联，联结关～。联～。\n⒍带子袜～。鞋～。\n⒎拴，绑，捆着送达～马。～绊其足。将车上的东西～着拿下来。〈引〉拘囚，拘束～狱。～于习俗。\n⒏挂，悬～念。群言～于口。\n⒐地层系统分类的第二级，比界小，相当于地质年代的纪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-系"},{"id":"glyph-kai-7d0a","script":"kai","character":"紊","reading":"wěn","description":"wěn：乱～乱。有条不～。纲颓纪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-紊"},{"id":"glyph-kai-7d20","script":"kai","character":"素","reading":"sù","description":"sù：(1)本色，白色～服。～丝。\n(2)颜色单纯，不艳丽～净。～淡。～妆。～雅。～描。\n(3)洁白的绢尺～（用绸子写的信）。\n(4)本来的，质朴、不加修饰的～质。～养。～性。～友（真诚淳朴的朋友）。\n(5)物的基本成分色～。毒～。维生～。\n(6)向来～来。～常。～志。平～。\n(7)白，不付代价～餐。\n(8)非肉类的食品，与荤”相对～食。～席。～油。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-素"},{"id":"glyph-kai-7d22","script":"kai","character":"索","reading":"suǒ","description":"suǒ：(1)大绳子或大链子～子。～道。钢～。绞～。线～。\n(2)搜寻，寻求～引。思～。搜～。探～。\n(3)讨取，要～还。～求。～取。勒～。\n(4)尽，毫无～然无味。\n(5)单独离群～居。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-索"},{"id":"glyph-kai-7d27","script":"kai","character":"紧","reading":"jǐn","description":"引申为物体受拉力或压力后呈现的紧张状态。同松”相对\n指经济不宽裕\n急促;迫切\n⒈紧，跟\"松\"相对。物体受拉力或压力之后的一种状态绑～。弦绷得太～。\n⒉收束把腰带～一～。\n⒊密切，靠得极近～邻。～接。～挨着。\n⒋急迫，短促，不宽裕时间～。功课～。工作～。过几年～日子。〈引〉因时间紧迫而加快抓～工作，手～点，可以提前完成任务。\n⒌事情严重或关系重大～要关头。～急事件。\n①激烈，迫切，不松弛工作～张。形势～张。\n②供应不足，难以应付市场～张。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-紧"},{"id":"glyph-kai-7d2b","script":"kai","character":"紫","reading":"zǐ","description":"zǐ：(1)在可见光中波长最短，红与蓝合成的颜色～红。～铜。～外线。～药水。\n(2)道教和某些朝代的统治者所崇尚的色彩，因而常在其宫室、服饰、用物前冠之以紫”～衣。～书（a.道经；b.皇帝诏书）。～诰（帝王诏令）。～台（神仙、帝王所居）。～气（祥瑞之气，多附会为帝王、圣贤或宝物出现的先兆）。～绶。～垣（皇宫）。～阙。～光阁。～禁城。～袍金带。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-紫"},{"id":"glyph-kai-7d2f","script":"kai","character":"累","reading":"lèi；léi；lěi","description":"léi：〔～～〕a.连续成串，如果实～～”；b.颓丧的样子，如～～若丧家之犬”。\n〔～赘〕a.多余，不简洁，如文字～～”；b.使人感到多余或麻烦的事物，如负重登高，不胜～～”（赘”均读轻声）。\n乏；\nlěi：(1)连续，重叠，堆积～计。～日。～积。～～。日积月～。连篇～牍。\n(2)照原数目多少而递增～进税。\n(3)连及，连带～及。牵～。拖～。\n乏；\nlèi：(1)疲乏，过劳劳～。～乏。\n(2)使疲劳病刚好，别再～着。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-累"},{"id":"glyph-kai-7d6e","script":"kai","character":"絮","reading":"xù","description":"xù：(1)棉花的纤维棉～。被～。\n(2)古代指丝的纤维，特指熟丝。\n(3)像棉絮的东西花～。芦～。柳～。\n(4)在衣被等物里铺棉花、丝绵等～被子。～棉袄。\n(5)连续重复，惹人厌烦～叨。～烦。～聒。～～叨叨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-絮"},{"id":"glyph-kai-7e41","script":"kai","character":"繁","reading":"fán；pó","description":"fán：(1)复杂～杂。～乱。删～就简。～难。～嚣。\n(2)多～多。～重（zhòng）。纷～。频～。～星。～忙。～芜。～博。\n(3)兴盛～茂。～荣。～华。\n(4)生物增生新个体～殖。～育。～衍。\n简；\npó：姓。\n〔～台〕中国河南省开封市东南的古迹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-繁"},{"id":"glyph-kai-7ea0","script":"kai","character":"纠","reading":"jiū","description":"缠绕\n⒈绳子。〈引〉缠绕～缠。\n⒊矫正，改过来～偏。～正。有错必～。\n①争执调解～纷。\n②杂乱交错～纷。\n纠jiǎo 1.见\"窈纠\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纠"},{"id":"glyph-kai-7ea2","script":"kai","character":"红","reading":"hóng","description":"后也指各种红色\n⒉见hóng。\n⒈赤，像火，鲜血那样的颜色～色。～花。火～。〈转义〉\n①革命的～军来了。～色娘子军。\n②喜庆操办～事。\n③光荣上～榜。\n④顺利，成功等～起来了。开门～。\n⑤先进的，众人尊敬的～旗手。～管家。\n⒉受宠信的人～人。\n⒊额外的利润～利。分～。\n①人世间。\n②繁华热闹的地方。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-红"},{"id":"glyph-kai-7ea4","script":"kai","character":"纤","reading":"xiān；qian","description":"用于拉船的绳索\n牵牲口的绳索\n⒈拉船的绳子～绳。揹～。\n①拉着纤绳使船前进。\n②旧指介绍买卖产业从中取利。\n纤jiān 1.刺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纤"},{"id":"glyph-kai-7ea6","script":"kai","character":"约","reading":"yuē","description":"共同商定的事,共同议定要遵守的条文\n盟约;相期的诺言\n缠束;环束\n⒈〈古〉套，捆缚～车。～紧。\n⒉拘束，限制～束。制～。\n⒊共同议定的要遵守的条款定～。条～。订～。公～。\n⒋商定或预先说定的事预～。如～。失～。\n⒌请～她来。特～。\n⒍简明，简要简～。\n⒎节俭节～。俭～。\n⒏大概～计。大～。\n⒐数学上指简化分数，即用公因数去除分子和分母4/8可～为1/2。\n⒈称重量把这袋米～一～，多少斤？\n约yào 1.总要;纲要。\n约dì 1.琴上圆形的星徽。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-约"},{"id":"glyph-kai-7ea7","script":"kai","character":"级","reading":"jí","description":"引申为等级,特指官阶爵位的品级\n石阶\n乃领宾者延之而\n⒈等次等～。下～。高～。提～。降～。\n⒊台阶石～。\n⒌颗，〈古〉指斩下的人头首～。斩虏数百～。\n级zhuì 1.缵列。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-级"},{"id":"glyph-kai-7eaa","script":"kai","character":"纪","reading":"jì","description":"开端,头绪\n要领\n纪jǐ姓。\n⒈丝的头绪丝缕有～。\n⒉记载～事。～要。～传。\n⒊记年单位\n①〈古〉十二年为一～。\n②公历以一百年为一世～。\n⒋年龄，岁数年～。\n⒌准则，制度师行有～。党～国法。加强～律。\n①法度国有～纲。\n②治理～纲其国。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纪"},{"id":"glyph-kai-7eab","script":"kai","character":"纫","reading":"rèn","description":"缝纫; 缝补\n连缀,联结\n⒈引线穿针～针。\n⒉缝补缝～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纫"},{"id":"glyph-kai-7eac","script":"kai","character":"纬","reading":"wěi","description":"缠捆,系束\n组织\n治理\n纬纱;织物的横丝\n东西向的道路或土地。与南北向的经”相\n⒈纬线，织布时使用梭子穿织的横纱或编织物的横线。\n⒉地理学上假设的与赤道平行之线。从赤道向北的称\"北纬\"，从赤道向南的称\"南纬\"，由赤道至南极或北极各为九十度。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纬"},{"id":"glyph-kai-7eaf","script":"kai","character":"纯","reading":"chún","description":"同一颜色的丝织品\n纯正,纯粹\n②纯净；不含杂质～天然食物。\n③纯粹；单一～黄。\n④纯熟工夫不～。\n【纯电感电路】除交变电源外，只含有电感元件的电路。电感两端的电压与电流同频，但电压比电流的相位超前π／z。线圈不消耗能量。\n【纯电容电路】除交变电源外，只含有电容元件的电路，在纯电容电路中，电容两端的电压与电流同频，但电压比电流的相位落后π／z。电容不消耗能量。\n【纯电阻电路】除交变电源外，只有电阻元件的电路，或有电感和电容元件，但它们对电路的影响可忽略。电压与电流同频且同相位。电阻将从电源获得的能量全部转变成内能\n【纯合体】基因型完全处于同质结合状态的生物体。如aa、aabb等基因型的生物。它们的自交后代是相对一致的，不会发生分离现象。\n【纯碱】见【碳酸钠】。\n【纯碱工业】以食盐、氨、水和二氧化碳为原料，以吸氨塔、碳酸化塔和滤碱机为主要设备制取纯碱的工业设施。\n【纯净物】只由一种单质或化合物所组成的物质，纯净物可分为单质和化合物两类。通常所指的纯净物是指含杂质少，具有一定纯度的物质。\n【纯利】总收支除去一切耗费后剩余的利润。\n【纯律】、音～音律的一种。根据自然之和弦制订。即在纯五度之间加入第五个泛音，使其成为自然之和弦，并顺次来确定音阶中各音的高度。纯律中基本音级间的音高关系，","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纯"},{"id":"glyph-kai-7eb1","script":"kai","character":"纱","reading":"shā","description":"轻细的丝麻织物,古时多以蚕丝为之。古亦作沙”\n麻、棉等纺成的细缕。俗称棉纱”或麻纱”\n今泛指用棉麻、化学纤维或其他材料制成的经纬线稀疏的织品\n⒈棉、麻等纺成的细缕，可用于捻线、织布棉～。麻～。\n⒉经纬线稀疏或有小孔的织物～布。羽～。窗帘～。〈引〉像纱布的铁～。尼龙～。\n纱miǎo 1.见\"纱纱\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纱"},{"id":"glyph-kai-7eb2","script":"kai","character":"纲","reading":"gāng","description":"事物的关键部分,事理的要\n⒈鱼网上的总绳网之～。〈引〉事物的关键部分～要。提～挈领。～举目张。\n⒉唐、宋时代成批运输货物的编组，每批的车辆、船只计数编号叫做\"一纲\"茶～。花石～。生辰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纲"},{"id":"glyph-kai-7eb3","script":"kai","character":"纳","reading":"nà","description":"收藏;收入\n纳”假借为接纳”;接受\n⒈收进，接收～入。接～。吐故～新。\n⒉接受采～。\n⒊缴付～税。～公粮。\n⒋享受～凉。～福。\n⒌缝补～鞋底。补补～ ～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纳"},{"id":"glyph-kai-7eb5","script":"kai","character":"纵","reading":"zòng","description":"南北称纵,东西称横。古作从衡”\n跟物体的长的一边平行的\n广泛\n谈道之余,纵言及文辞,…,非凡子\n⒈发，放～兵。～火。～虎归山。\n⒉放任，无拘束～容。放～。～情歌唱。\n⒊放开，释放～目远望。七擒七～。\n⒋身体猛然向前或向上～身跳过去。\n⒌即使～使。～有困难，也能克服。\n⒍竖，直，南北的方向，跟\"横\"相对～线。～剖。站成～队。\n⒎深广，从前到后的～深。\n⒏起皱纹纸揉～了。\n①引身，举身。\n②行动放肆。\n纵zǒng 1.见\"纵纵\"。 2.通\"总\"。掌握;统率。 3.通\"总\"。古代的一种丝织品。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纵"},{"id":"glyph-kai-7eb7","script":"kai","character":"纷","reading":"fēn","description":"旗上的飘带\n花边\n祸乱;灾难\n争执;纠纷\n⒈众多，杂乱～至沓来。～杂的声音。～乱的人群。\n①人或事物接二连三地～ ～响应献血。\n②既多又杂乱议论～ ～。落叶～ ～。\n⒉争执～争。排难解～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纷"},{"id":"glyph-kai-7eb8","script":"kai","character":"纸","reading":"zhǐ","description":"冥钱,旧俗为祭奠鬼神而焚化的纸钱\n进。\n⒉量词一～空文。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纸"},{"id":"glyph-kai-7eb9","script":"kai","character":"纹","reading":"wén","description":"物品表面的皱痕,或指水面涟漪\n皮肤上的纹理\n指纹银\n以彩色线条刻画在物体表面\n陶器、陶片发见最多,西阴村遗址发见的多\n纹wén丝织品上的花纹，泛指花纹绸～。布～。条～。指～。木～。～理。\n纹wén丝织品上的花纹，泛指花纹绸～。布～。条～。指～。木～。～理。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纹"},{"id":"glyph-kai-7eba","script":"kai","character":"纺","reading":"fǎng","description":"通绷”。捆绑,悬挂;束缚\n绸属;素纱\n⒈将丝、棉、麻、毛、化工纤维等制成纱或线～细纱。～毛线。\n⒉质地比绸子轻薄的丝织物或绸子的一种～绸。蜀～。\n纺bǎng 1.悬空绑着;捆缚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纺"},{"id":"glyph-kai-7ebd","script":"kai","character":"纽","reading":"niǔ","description":"比喻事物的根本,关键\n纽绊。器物上用以提携或系绳带的部件\n钮扣\n⒈器物上可以提起来或系挂的部分秤～。印～。\n⒉扣合衣物的东西～扣子。塑料～扣。\n⒊系结用的带子。〈喻〉连结、根本或关键～带。枢～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-纽"},{"id":"glyph-kai-7ebf","script":"kai","character":"线","reading":"xiàn","description":"细长如线的东西\n线索\n⒈棉、麻、丝、毛、锦纶或金属等制成的细长东西棉～。丝～。毛～。电～。尼龙～。\n⒉像线的光～§外～〗～。铁道～。\n⒊细微，极少一～希望。\n⒋几何学上称只有长度而没有宽度和厚度的直～。曲～。\n⒌边缘交界处防～。火～。岸～。国境～。〈喻〉所接近的某种边际生命～。死亡～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-线"},{"id":"glyph-kai-7ec3","script":"kai","character":"练","reading":"liàn","description":"练习;操演\n漂洗;洗涤\n⒈白色的熟绢江平如～。\n⒉把丝麻或织品煮得柔软而洁白。\n⒋反复学习，再三操作～习。～基本功。～技术。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-练"},{"id":"glyph-kai-7ec4","script":"kai","character":"组","reading":"zǔ","description":"⒈〈古〉丝带，编织织～。素丝～之。\n⒉结合，构成～合。～成。\n⒊若干人结合成的单位学习～。科研～。\n⒋有规律、有系统的，合为一体的～词。～歌。～画。\n⒌量词两～铅笔。\n①有目的、有秩序、有系统的结合起来～织春节晚会。\n②按一定的任务、目的建立起来的集体党～织。体育～织。\n③事物的组成系统或各部分之间的关系～织庞大。～织关系。\n④多细胞动、植物体中构成器官的基本单位上皮～织。肌肉～织。\n⑤纺织品经纬的结构这是斜纹～织的布。那是平纹～织的布。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-组"},{"id":"glyph-kai-7ec5","script":"kai","character":"绅","reading":"shēn","description":"旧指地\n⒈〈古〉士大夫系的大带子，也指束带佩～。～之束之。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绅"},{"id":"glyph-kai-7ec6","script":"kai","character":"细","reading":"xì","description":"纤细⊥粗”相\n⒈微，小，跟\"大\"、\"巨\"、\"粗\"等相对～微。～小。～末。～声。～铁丝。～石沙。\n⒉精致～致。精～。景德镇～瓷。\n⒊周密～密。仔～。大胆心～。精打～算。～心观察。\n⒋详～说。详～。\n⒌微小的，具体的事无巨～。注意～节。\n⒍一点一滴，俭朴～水长流。他们过日子很～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-细"},{"id":"glyph-kai-7ec7","script":"kai","character":"织","reading":"zhī","description":"织zhì 1.用染丝织成的丝织品。 2.通\"帜\"。旗帜;标志。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-织"},{"id":"glyph-kai-7ec8","script":"kai","character":"终","reading":"zhōng","description":"终了;结束。与始”相对\n⒈末了，完了，结束，跟\"始\"相对～了。～点。～止。剧～。〈引〉死，生命完结寿～。\n⒉毕竟，到底～归。～于。～究。～见成效。\n①久远，永远。\n②经常。\n③往昔，自古以来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-终"},{"id":"glyph-kai-7eca","script":"kai","character":"绊","reading":"bàn","description":"羁绊;拘束;束缚\n用绳子把足系住\n走路或跑步时被别的东西挡住或缠住\n绊 bàn 挡住或缠住，使其跌倒或行走不方便～倒、～手～脚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绊"},{"id":"glyph-kai-7ecd","script":"kai","character":"绍","reading":"shào","description":"介绍,为人引见,使相互认识\n绍我周王见休。\n⒈继续，接续～述。～世而起。\n⒉联系～介。介～。\n绍chāo 1.缓慢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绍"},{"id":"glyph-kai-7ece","script":"kai","character":"绎","reading":"yì","description":"引出头绪,寻求事理\n陈述\n陈列\n继续,连续不断","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绎"},{"id":"glyph-kai-7ecf","script":"kai","character":"经","reading":"jīng","description":"渭水支流。有南、北二源。北源出宁夏六盘山东麓固原县;南源出甘肃省华亭县,至平凉县境合流后,又东南流入陕西省,至高陵县入渭河 。如泾渭分明\n古州名\n县名\n⒈织布的纵线叫\"经\"，横线叫\"纬\"。\n⒉地面上东与西距离的度数称\"经度\"。地理上假定通过南极、北极同赤道成直角的线，以英国格林尼治天文台原址的子午线为起点，以东叫\"东经\"，以西叫\"西经\"，东、西各一\n百八十度。\n⒋具有典范性的～典。\n⒌宗教中宣讲教义的书佛～。圣～。古兰～。\n⒎禁受，承受，忍受～受。饱～风霜。\n⒏〈表〉过去而且已完成～历。曾～。已～。身～百战。\n⒐通过，路过～手。～过。途～西安。\n⒑中医把人体气血运行的主干叫\"经\"～脉。～络。\n⒒妇女的月经～期。\n⒓上吊，缢死自～。～其颈于树枝。\n①经营，管理擅长～纪。\n②经纪人，为买卖双方撮合，从中获取佣金的人。\n①社会生产关系的总合，也是政治和思想意识等上层建筑的基础，即经济基础。\n②国民经济的总称或指国民经济的某个部门～济状况。工业～济。\n③节约，便宜，化费少～济实惠。\n④收支状况～济宽裕。\n①从实践得来的知识或技能。\n②经历。\n经jìng 1.谓织布前，于机杼上绷齐并梳整纱缕，使成为经线。 2.通\"径\"。直径。 3.通\"径\"。小路。 4.通\"径\"。直。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-经"},{"id":"glyph-kai-7ed1","script":"kai","character":"绑","reading":"bǎng","description":"绑票\n绑带,绑带儿\n绑 bāng 用绳、带等缠或捆～腿。\n【绑架】用强力把人劫走。\n【绑票】匪徒把人劫走，强迫被绑架者的家属或有某种特殊关系的人用钱去赎。\n绑bǎng 1.用绳﹑带等缠绕或捆扎。 2.犹绑票。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绑"},{"id":"glyph-kai-7ed2","script":"kai","character":"绒","reading":"róng","description":"丝、棉纱或羊毛等的纺织物\n熟丝\n绒布,上面有一层绒毛的纺织品\n⒈柔软细小的毛～毛。羽～。鸭～。\n⒉带有细绒的纺织品～衣。灯草～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绒"},{"id":"glyph-kai-7ed3","script":"kai","character":"结","reading":"jié","description":"植物生长果实\n坚硬;牢固\n健壮\n用绳、线、皮条等绾成的疙瘩\n旧时向官府承担责任或承认了结的书面的字据\n关键\n被联结的状态\n通髻”。总发,挽发而结之于顶\n⒈系，编织，扎缚打～。～绳。～毛衣。张灯～彩。〈引〉问题所在处症～。又指编结成的东西活～←蝶～。\n⒉聚，凝聚水已～冰。～晶体。\n⒊合，联合～合。～社。～交。\n⒋了毕，收束～业。～束。～账。\n⒌作为保证的一种字据具～。\n①各个组成部分的相互排列搭配 文章～构。经济～构。\n②建筑物上承担重力的构造砖木～构。\n③内部构造组织～构。机器～构。\n①植物长成所结的果实。\n②事情的终了或发展到一定阶段那件事已有了～果。\n③旧小说中指将人杀死～果了那厮的性命。\n⒔见jiē。\n⒈植物长果实或种子这棵梨树，今年刚～果。\n①植物长果实或种子。\n②坚固，牢靠这堵墙挺～实。\n③健壮他虽老，但身体很～实。\n⒋见jié。\n结成。\"执雠\"。\n⑾ 朋友;至交。\n⑿殷代的世家大族。\n结jì 1.发髻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-结"},{"id":"glyph-kai-7ed5","script":"kai","character":"绕","reading":"rào","description":"环绕\n迂回绕过\n⒈缠～线。\n⒉纠缠，弄迷糊把他～住。这两个字总算将他～着了。\n⒊围着转～场一周。月亮～地球运行。\n⒋走弯路或迂回的路～了一段路。～到敌人背后。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绕"},{"id":"glyph-kai-7ed8","script":"kai","character":"绘","reading":"huì","description":"绘画\n用言辞形容","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绘"},{"id":"glyph-kai-7ed9","script":"kai","character":"给","reading":"gěi","description":"使对方得到或遭受到\n让;使;叫\n表示对象、目的,相当于为”、替”\n给伤员包扎\n引进动作行为的主动者,或表示被动语态,相当于被”\n表示方向,相当于朝”、对”、向”\n⒈交，付，送与请～我一支笔。〈引〉将动作或态度加于对方～他一巴掌。\n⒉介词。\n①替，为～人民办好事。\n②被，遭受～水冲走了。\n⒊助词。\n②〈方〉走时随手～门关好。\n⒋见jǐ。\n⒈供应～养。供～。自～自足。\n⒉富裕，丰足百姓充～。人～家足。\n⒊见gěi。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-给"},{"id":"glyph-kai-7eda","script":"kai","character":"绚","reading":"xuàn","description":"通侚”。迅疾的样子\n辉映;照耀\n点缀\n绚xuàn有文彩，色彩华丽～丽。～烂。素章增～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绚"},{"id":"glyph-kai-7edc","script":"kai","character":"络","reading":"luò","description":"⒈网状的东西。用于一些口语丝瓜～。\n①线绳结成的网状袋子用塑料～子装洗脸盆。\n②绕线、绕纱等的器具。\n⒈网状的东西脉～。经～。丝瓜～。\n⒉罩住头上～着发网。\n⒊缠绕，缠裹，环绕～线。笼山～野。\n⒋拉拢笼～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-络"},{"id":"glyph-kai-7edd","script":"kai","character":"绝","reading":"jué","description":"引申为断,断绝\n以绝秦望。\n秦王惊,自引而起,袖\n⒈断，隔断～交。～缘体。\n⒉完，完全，穷尽气～。～无例外。～处逢生。敌人陷入～境。\n⒊极，非常～密。～伦。～妙。～大多数。～无仅有。〈引〉高超，独特～技。～招。\n⒋一定，无论如何～不允许贪赃枉法。\n①极端，非常～顶的聪明。\n②最高峰泰山～顶。会当凌～顶。\n①最，极～对可靠。\n②完全，一定～对办得好。\n③无条件的，不受任何限制的～对存在于相对之中，在相对中有～对。\n④只根据一个条件测算的～对温度。～对高度。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绝"},{"id":"glyph-kai-7ede","script":"kai","character":"绞","reading":"jiǎo","description":"缠绕\n⒈拧合，扭紧～手巾。～棕绳。\n⒉用绳把人勒死或吊死的一种酷刑～刑。～架。\n⒊量词两～毛线。三～细纱。\n绞xiáo 1.苍黄色。 2.借指苍黄色单衣。 3.古代丧礼中敛尸用的束带。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绞"},{"id":"glyph-kai-7edf","script":"kai","character":"统","reading":"tǒng","description":"世代相继的系统\n纲纪,准则\n鞋袜等的筒状部分\n⒈丝的头绪抽其～。\n⒉事物的连续或彼此相连的关系系～。传～。血～。\n⒊纲要，纲领不知其～。\n⒋总括，综合，全面地～计。～筹。～理。\n⒍主管，率领～管。～辖。～兵百万。\n①部分结合成整体，分歧趋于一致全国～一。意见～一。\n②一致的，单一的～一认识。～一领导。\n①凭借政权来控制、治理国家或地区。\n②占绝对优势，支配控制别的事物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-统"},{"id":"glyph-kai-7ee2","script":"kai","character":"绢","reading":"juàn","description":"麦青色的丝织物\n丝织品的通称\n手绢\n⒈一种薄的生丝织品，〈古〉多用作于书画、装璜等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绢"},{"id":"glyph-kai-7ee3","script":"kai","character":"绣","reading":"xiù","description":"著我绣夹裙。\n朝绣夹裙。\n⒈用彩色的丝线、棉线等在布、绸等上面刺成花纹、图象、文字等刺～。～花。～图。～字。\n⒉刺绣品苏～。湘～。蜀～。绒～。〈引〉华丽，精美，漂亮花梁～柱。～羽衔花他自得。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绣"},{"id":"glyph-kai-7ee7","script":"kai","character":"继","reading":"jì","description":"继承","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-继"},{"id":"glyph-kai-7ee9","script":"kai","character":"绩","reading":"jì","description":"把麻纤维披开接续起来搓成线\n承继\n成就;功业\n庶绩\n⒈缉线，将麻搓成绳或线纺～。\n⒉功业，成果业～。巨大成～。战～辉煌。丰功伟～。\n绩jī 1.功业。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绩"},{"id":"glyph-kai-7eea","script":"kai","character":"绪","reading":"xù","description":"头绪,开端\n情绪,心情\n⒈丝头。〈喻〉开端头～。论端究～。\n⒉世系，事业先～。续未竟之～。\n⒊心情、思想等心～。情～。思～。意～。\n⒋残余的～余。～风。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绪"},{"id":"glyph-kai-7eed","script":"kai","character":"续","reading":"xù","description":"继续\n⒈连接，接上一段～假。～编。断长～短。\n⒉连接不断连～。继～。延～。\n⒊继承～祖。\n⒋添加将茶～上。肉汤里再～些水。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-续"},{"id":"glyph-kai-7ef0","script":"kai","character":"绰","reading":"chuō","description":"姿态柔美\n隐隐约约\n端正\n吹拂\n搅乱\n①抓取顺手～起棍子。\n②同'焯'。又见chuò\n绰 chuò富足宽～。又见chāo。\n【绰绰有余】形容很宽绰，用不完。\n【绰号】外号。\n【绰约】形容女子体态柔美的样子。\n⒈匆忙抓起～起木凳。\n⒉通\"焯\"～波菜。\n⒈宽裕，舒缓宽～。～有余裕。～ ～有余。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绰"},{"id":"glyph-kai-7ef3","script":"kai","character":"绳","reading":"shéng","description":"⒈由两股或两股以上的棉、麻、棕、草、金属丝、化学纤维等拧成的条状物～索。棕～子。尼龙～。\n⒉木工用的墨线～墨。〈喻〉标准，规矩，法则，法度有～可依。\n⒊制裁，约束～之以法。\n绳mǐn 1.见\"绳绳\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绳"},{"id":"glyph-kai-7ef4","script":"kai","character":"维","reading":"wéi","description":"隅,角落\n⒉系，连结～系。\n⒊保持，保全，保护～持。～护。\n⒌通\"惟\"。思考～万世之安。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-维"},{"id":"glyph-kai-7ef5","script":"kai","character":"绵","reading":"mián","description":"同义\n通棉”\n丝絮状物\n隋堤上,曾见几番,拂水\n⒈蚕丝结成的片或团丝～。\n⒊连续不断～延。～地千里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绵"},{"id":"glyph-kai-7ef7","script":"kai","character":"绷","reading":"bēng","description":"缠束;包扎\n张紧,在两端或边上用力造成平直的坚挺状态\n猛地弹起\n稀疏地缝住或用针别上\n勉强支持;硬撑\n①拉紧；紧张不要把弦～得太紧了。\n①不舒展～着脸。\n②勉强支撑～住劲往下讲。又见bēng；bèng。\n①裂开～了一道口子。\n②用在'硬、直、亮'一类形容词的前面，表示程度深～硬、～直、～亮。又见bēng;běng。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绷"},{"id":"glyph-kai-7ef8","script":"kai","character":"绸","reading":"chóu","description":"捆缚\n通稠”。致密;稠密\n绸 chóu薄而软的丝织品～缎、红～。\n【绸缪】\n①缠绵情意～。\n②用绳索紧密缠捆。引申为修补未雨～。\n【绸舞】中国一种传统舞蹈。表演者手执彩绸舞动并配以各种步伐。多为单人表演，现也有集体表演。多用于传统戏曲民间舞蹈表演及其他喜庆场合。\n⒈绸子，一种薄而细软的丝织品～缎。纺～。\n绸tāo 1.缠裹;套。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绸"},{"id":"glyph-kai-7efc","script":"kai","character":"综","reading":"zōng；zeng","description":"织布机上使经线上下交错以受纬线的一种装置\n综光瓦亮\n灯光下,大理石的地板锃光瓦亮\n综亮\n皮鞋擦得锃亮\n总聚;总合\n⒈聚总，集合，组合～合。错～复杂。\n⒈织布机上使经线上下交错，便于纬线穿过的一种装置 。\n综zòng 1.织机上使经线上下交错以便梭子通过的装置。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-综"},{"id":"glyph-kai-7efd","script":"kai","character":"绽","reading":"zhàn","description":"皮肉破裂\n饱满、开裂。特指花果\n缝补\n破费;花费\n多参白水江湖酒,少绽黄边风月钱\n绽zhàn裂开，破裂～开。破～。皮开肉～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绽"},{"id":"glyph-kai-7eff","script":"kai","character":"绿","reading":"lǜ","description":"通菉”。一种野菜\n绿林\n绿林好汉\n绿林起义\n⒈一般草和树叶的颜色。\n②旧时指上山为匪，抢劫财物的集团。\n⒈像一般草或树叶的颜色，蓝和黄混合而成的颜色～叶。～水青山。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-绿"},{"id":"glyph-kai-7f00","script":"kai","character":"缀","reading":"zhuì","description":"著作。组织文字以成篇章\n⒈缝，连结～合。～上。～补。～辞成文。\n⒉装饰点～。\n缀chuò 1.拘束。 2.牵制。 3.通\"辍\"。停;中止。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缀"},{"id":"glyph-kai-7f05","script":"kai","character":"缅","reading":"miǎn","description":"缅甸的简称\n遥远\n尽貌\n缅miǎn遥远～想。～怀故土。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缅"},{"id":"glyph-kai-7f06","script":"kai","character":"缆","reading":"lǎn","description":"许多股绞成的粗绳\n拴;系\n⒉使用绳索将船系住～船。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缆"},{"id":"glyph-kai-7f09","script":"kai","character":"缉","reading":"jī","description":"搜捕\n继续\n会合;和睦。通辑”\n适道已来,\n⒈捉拿，搜捕～拿。～获。～私。\n⒉见qī。\n⒈密针细缝法，一针对一针地缝～鞋口。\n⒉见jibh。\n缉jí 1.协调;和合。 2.收集;编辑。 3.编织;裁制。 4.理;整治。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缉"},{"id":"glyph-kai-7f0e","script":"kai","character":"缎","reading":"duàn","description":"一种质地厚密而有光泽的丝织物\n缎 质地厚密、一面光滑的丝织品锦～。\n缎duàn 1.同\"?\"。贴于鞋跟的革片﹑丝绦之属。 2.一种质地厚密而有光泽的丝织物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缎"},{"id":"glyph-kai-7f13","script":"kai","character":"缓","reading":"huǎn","description":"慢;不急迫。与急”相对\n柔软\n⒈慢，跟\"急\"相对～慢。～步。～急轻重。～ ～来迟。\n⒉迟，推迟～期。～办。～刑。～兵之计。\n⒊宽松，平和已～和。～冲地带。\n⒋苏醒，恢复他昏过去了，刚～过来。休息一会儿，～ ～气。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缓"},{"id":"glyph-kai-7f14","script":"kai","character":"缔","reading":"dì","description":"引申为郁结\n结合\n订立\n构造,建造\n约束;限制\n缔 dì结合；订立；～约。\n【缔约】订立条约。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缔"},{"id":"glyph-kai-7f15","script":"kai","character":"缕","reading":"lǚ；lv","description":"泛指细而长的东西,线状物\n⒈线千丝万～。\n⒉详尽地，一条一条地～陈。～析。\n⒊量词两～麻线。三～炊烟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缕"},{"id":"glyph-kai-7f16","script":"kai","character":"编","reading":"biān","description":"交织,编结\n编辑;创作\n①把细长条状物交叉地组织起来～花篮。\n②按一定的顺序组织排列～号、～班。\n⑤捏造～造谎言。\n⑥成本的书人手一～。\n⑦书籍按内容划分的单位上～、下～。\n【编队】\n①将人群或运输工具等编成一定的队形。\n【编户】编入户籍的平民。中国古代自商鞅变法开始，历代均把平民编入政府户籍，称编户。\n【编磬】古代打击乐器。由16块石制或玉制的磬组成。用小木槌击奏。周代以来用于雅乐。\n机器执行，必须将它译成机器语言程序。\n【编译员】带有编辑性质的翻译人员。\n【编钟】古代打击乐器。把一系列铜制的钟挂在木架上组成，用小木槌击奏。各时代形状大小不一，枚数也不相同。\n【编撰】编辑；编写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-编"},{"id":"glyph-kai-7f18","script":"kai","character":"缘","reading":"yuán","description":"器物的边沿\n原故,理由\n因缘;缘分\n言谈大自缘。\n画与建\n⒈边边～。外～。\n⒉沿着，顺着～溪行。\n⒊遵循，依照～法而治。\n⒋爬，攀附～木而上。攀～。夤～。\n⒌人与人的关系人～。血～。\n⒍宿命论者指人与人或人与事所谓\"命中注定的遇合机会\"～分、有～、机～等等不过是自圆其说。\n⒎因为，因由～故。～由。～何至此？\n缘yuàn 1.衣服边上的镶绲;衣服的边。 2.给衣履等物镶边或绲边。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缘"},{"id":"glyph-kai-7f1a","script":"kai","character":"缚","reading":"fù","description":"约束;限制\n绳索\n量词。用\n缚 fù缠束，捆绑束～。～鸡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缚"},{"id":"glyph-kai-7f1d","script":"kai","character":"缝","reading":"féng","description":"补合\n缝合处\n缝 féng用针线连缀～补。\n【缝纫】剪裁制做服装。\n⒈裂开的或自然显露的窄长口子一条裂～。有道～隙。墙上有～。\n⒉接合的地方无～钢管。这是～合口留下的痕迹。\n⒊空子～隙。见～插针。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缝"},{"id":"glyph-kai-7f20","script":"kai","character":"缠","reading":"chán","description":"纠缠;搅扰\n应付;对付\n①缠绕～脚。\n②纠缠；搅扰你不要再来～我了，我正忙着呢！\n③应付。\n②委婉动人曲调～。\n【缠头】古代歌舞的人把锦帛缠在头上作装饰，叫'缠头'。又指赠送给歌舞者的锦帛或财物。\n⒈盘绕，扎束～绕。～绷带。\n⒉搅扰，牵绊纠～。有事～着。\n⒊〈方〉应付跟这种人难～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缠"},{"id":"glyph-kai-7f24","script":"kai","character":"缤","reading":"bīn","description":"紊乱\n【缤纷】繁多而杂乱的样子彩旗～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缤"},{"id":"glyph-kai-7f29","script":"kai","character":"缩","reading":"suō","description":"收缩\n⒈用绳子捆起来。\n⒉退～回。退～。\n⒊蜷，收敛收～。畏～。～手～脚。\n⒋减少，变小，变短压～。紧～。～减。～小。～短。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缩"},{"id":"glyph-kai-7f2d","script":"kai","character":"缭","reading":"liáo","description":"围绕;绕道而行\n⒈缠绕，纷乱～绕。眼花～乱。〈引〉环绕～以周墙。\n⒉用针线缝缀～缝儿。～衣边。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缭"},{"id":"glyph-kai-7f30","script":"kai","character":"缰","reading":"jiāng","description":"马缰绳\n缰绳","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缰"},{"id":"glyph-kai-7f34","script":"kai","character":"缴","reading":"jiǎo","description":"缠绕\n交纳\n扭动;搅动\n⒈交出，交纳～卷。～税。\n⒉收取，强迫交出收～。～械。～获归公。\n⒈拴在箭上的生丝绳，用于射鸟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缴"},{"id":"glyph-kai-7f38","script":"kai","character":"缸","reading":"gāng","description":"gāng：(1)盛东西的器物，圆筒状，底小口大。用陶、瓷、玻璃等制成水～。～子。\n(2)用砂子、陶土等混合而成的一种质料～瓦。～盆。\n(3)像缸的器物汽～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缸"},{"id":"glyph-kai-7f3a","script":"kai","character":"缺","reading":"quē","description":"quē：(1)不够～乏。～少。～憾。欠～。～漏。\n(2)残破～点。～口。～陷。\n(3)空额（指职位）～额。补～。\n(4)该到而未到～勤。～席。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-缺"},{"id":"glyph-kai-7f50","script":"kai","character":"罐","reading":"guàn","description":"guàn：盛东西或汲水用的瓦器，亦泛指各种圆筒形的盛物器皿瓦～。铁～。～头。拔火～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罐"},{"id":"glyph-kai-7f51","script":"kai","character":"网","reading":"wǎng","description":"泛指多孔而状如网的东西\n喻指法律,\n⒈用绳线结成的渔猎工具撒～。设～。鱼～。\n⒉形状像网的～兜。蛛～。钢丝～。\n⒊用网捕捉～鸟。～着了大鱼。\n⒋像网那样的组织或系统通讯～。铁路～。\n①渔猎用的网。\n②搜求，设法招致～罗英才。有时含贬义～罗党羽。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-网"},{"id":"glyph-kai-7f55","script":"kai","character":"罕","reading":"hǎn","description":"hǎn：(1)稀少稀～。～见。～俦（很少与之相比的）。～世之宝。人迹～至。\n(2)古代称捕鸟用的长柄小网。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罕"},{"id":"glyph-kai-7f57","script":"kai","character":"罗","reading":"luó","description":"轻软的丝织品\n⒈捕鸟的网～网。\n⒉张网捕捉～雀。\n⒊招请，搜集～致。收～。～天下之士。\n⒋排列，散布～列。星～棋布。\n⒌稀疏而轻软的丝织品～衫。～扇。\n⒍一种细密的筛子绢～。铜丝～。\n⒎用罗筛东西～面。\n⒐同\"脶\"。手指纹。\n罗luo 1.语气词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罗"},{"id":"glyph-kai-7f5a","script":"kai","character":"罚","reading":"fá","description":"对违反规定或有过失者给予惩处，如处罚、罚款。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-7f62","script":"kai","character":"罢","reading":"bà","description":"遣返,遣归\n停止\n①中止某种活动～课、～工。\n②免去；解除～免。\n【罢黜】\n①贬低并排斥～百家。\n【罢论】不必再论说；不必再论说的事此事已成～。\n罢pí 1.疲劳;衰弱。 2.疲敝;惫乏。 3.慰劳。 4.弱;无能。 5.无行。参见\"罢士\"﹑\"罢女\"。 6.败，失败。\n罢bǐ 1.离散;分散;散开。\n罢pì 1.见\"罢辜\"。\n罢bǎi 1.见\"郎罢\"。\n罢ba 1.语气词。同\"吧\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罢"},{"id":"glyph-kai-7f69","script":"kai","character":"罩","reading":"zhào","description":"zhào：(1)覆盖，覆盖物体的东西笼～。灯～。～衣。\n(2)捕鱼或养鸡鸭等用的竹笼子鸡～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罩"},{"id":"glyph-kai-7f6a","script":"kai","character":"罪","reading":"zuì","description":"zuì：(1)犯法的行为犯～。～人。认～。有～。～恶。～名。～魁。～行。～证。～责。～孽（迷信的人认为应受到报应的罪恶）。～不容诛。\n(2)过失，把过失归到某人身上功～。～愆。～尤（尤”，过失，罪过）。归～于人。\n(3)刑罚判～。畏～。待～。请～。\n(4)苦难，痛苦受～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-罪"},{"id":"glyph-kai-7f6e","script":"kai","character":"置","reading":"zhì","description":"zhì：(1)放，摆，搁安～。布～。～放。～身。位～。～信。～评。～疑。～辩。推心～腹。～若罔闻。～之度外。\n(2)设立，设备装～。设～。\n(3)购买添～。～办。～备。～买。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-置"},{"id":"glyph-kai-7f72","script":"kai","character":"署","reading":"shǔ","description":"shǔ：(1)办理公务的机关专～。公～。官～。\n(2)布置部～。\n(3)签名，题字签～。～名。～字。\n(4)暂代～理。兼～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-署"},{"id":"glyph-kai-7f8a","script":"kai","character":"羊","reading":"yáng；xiáng","description":"yáng：(1)哺乳动物，反刍类，一般头上有一对角，品种很多绵～。黄～。羚～。～羔。～毫。～肠线。～肠小道。\n(2)姓。\nxiáng：古同祥”，吉祥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羊"},{"id":"glyph-kai-7f8e","script":"kai","character":"美","reading":"měi","description":"měi：(1)好，善～德。～学。～谈。审～。～丽。～容（美化容貌）。～不胜收。\n(2)得意，高兴～滋滋的。\n(3)称赞，以为好赞～。～言。～誉。\n(4)指亚美利加洲”（简称美洲”）北～。南～。\n(5)指美国”～元。～籍华人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-美"},{"id":"glyph-kai-7f94","script":"kai","character":"羔","reading":"gāo","description":"gāo：(1)小羊羊～。～羊。～儿皮。\n(2)泛指动物的幼崽儿鹿～儿。牛～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羔"},{"id":"glyph-kai-7f9a","script":"kai","character":"羚","reading":"líng","description":"líng：〔～羊〕哺乳动物，种类很多，角可入药，如～～挂角”（传说羧羊夜晚睡觉时，以角挂于树上，脚不着地，猎人难以找寻它的踪迹。喻诗文奥妙超脱，不露雕琢痕迹）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羚"},{"id":"glyph-kai-7f9e","script":"kai","character":"羞","reading":"xiū","description":"xiū：(1)感到耻辱～耻。～辱。～恶。\n(2)难为情，害臊害～。～惭。～臊（sào）。～愧‖～。～赧（因害臊而红了脸的样子）。～怯。～涩。\n(3)使难为情～人。你别～我。\n(4)进献～玉芝以疗饥”。\n(5)同馐”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羞"},{"id":"glyph-kai-7fa1","script":"kai","character":"羡","reading":"xiàn","description":"xiàn：(1)因喜爱而希望得到贪～。～慕。～妒。艳～。临渊～鱼。\n(2)有余，余剩余～。以～补不足”。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羡"},{"id":"glyph-kai-7fa4","script":"kai","character":"群","reading":"qún","description":"qún：(1)相聚成伙的，聚集在一起的～岛。～山。～书。～芳。～居。～落（luò）。～集。～雕。～蚁附膻（许多蚂蚁附着在有膻味的东西上；喻臭味相投的人趋炎附势，追逐私利）。\n(2)众人～众。～情。～雄。～策～力。～威～胆。\n(3)量词，用于成群的人或物一～孩子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-群"},{"id":"glyph-kai-7fb9","script":"kai","character":"羹","reading":"gēng","description":"gēng：用蒸煮等方法做成的糊状、冻状食物～汤。肉～。鸡蛋～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羹"},{"id":"glyph-kai-7fbd","script":"kai","character":"羽","reading":"yǔ","description":"yǔ：(1)鸟的毛～毛。～绒。～书。～衣。～扇。～族（指鸟类）。～旗。～檄（羽书）。\n(2)鱼类或昆虫的翅膀，道教传说中指会飞的仙人～翼。～翰（翅膀）。～士（a.会飞的仙人；b.道士）。\n(3)箭上的羽毛，借指箭～猎。\n(4)古代五音之一，相当于简谱6”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-羽"},{"id":"glyph-kai-7fc1","script":"kai","character":"翁","reading":"wēng","description":"wēng：(1)老头儿老～。渔～。塞～失马，焉知非福”。\n(2)父亲家祭无忘告乃～”。\n(3)丈夫的父亲～姑（公婆）。\n(4)妻子的父亲～婿。\n(5)姓。\n(6)鸟颈毛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翁"},{"id":"glyph-kai-7fc5","script":"kai","character":"翅","reading":"chì","description":"chì：(1)鸟和昆虫等用来飞行的器官～膀。～翼。插～难飞。\n(2)翘出像翅的东西～果。纱帽～。\n(3)古同啻”，但，只。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翅"},{"id":"glyph-kai-7fd4","script":"kai","character":"翔","reading":"xiáng","description":"xiáng：盘旋地飞而不扇动翅膀滑～。翱～。\n〔～实〕详细而确实。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翔"},{"id":"glyph-kai-7fd8","script":"kai","character":"翘","reading":"qiào","description":"鸟尾\n泛指动物的尾部\n抬起\n⒈鸟尾巴上的长毛。\n⒉举起，抬起，向上～望。～足。～首。\n⒊板状物因由湿变干而引起弯曲不平柜子晒～了。门板～棱了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翘"},{"id":"glyph-kai-7fe0","script":"kai","character":"翠","reading":"cuì","description":"cuì：(1)绿色～绿。苍～。～微（青绿的山色，亦泛指青山）。\n(2)指翡翠”（硬玉）～玉。～镯。珠宝～钻。\n〔～鸟〕属鸣禽类，形似杜鹃，嘴长，头部深橄榄色，有青绿色斑纹，背青绿色，腹赤褐色，尾短，捕食小鱼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翠"},{"id":"glyph-kai-7fe9","script":"kai","character":"翩","reading":"piān","description":"piān：(1)很快地飞。\n(2)轻快，飘忽～然。～跹。～～。～若惊鸿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翩"},{"id":"glyph-kai-7ff0","script":"kai","character":"翰","reading":"hàn","description":"hàn：(1)长而坚硬的羽毛理翩振～。\n(2)借指毛笔和文字、书信等～苑。～墨（笔墨，借指诗文书画）。～藻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翰"},{"id":"glyph-kai-7ffb","script":"kai","character":"翻","reading":"fān","description":"fān：(1)歪倒（dǎo），反转，变动位置，改变推～。～车。～卷。～滚。～腾。～工。～阅。～身。～地。～修。～建。～改。～脸。人仰马～。～江倒海（形容水势浩大，多喻力量或气势非常壮大）。～云覆雨（喻反覆无常或玩弄手段）。\n(2)数量成倍的增加～番。\n(3)越过～越。\n(4)飞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翻"},{"id":"glyph-kai-7ffc","script":"kai","character":"翼","reading":"yì","description":"yì：(1)翅膀～翅。比～双飞。卵～。羽～。～护。～蔽。\n(2)左右两侧中的一侧左～。侧～。\n(3)帮助，辅佐～助。\n(4)古同翌”，明天，明年。\n(5)星名，二十八宿之一。\n(6)姓。\n〔～～〕a.谨慎，如小心～～”；b.严整有秩序；c.繁盛，众多。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-翼"},{"id":"glyph-kai-8000","script":"kai","character":"耀","reading":"yào","description":"yào：(1)光线照射～眼。闪～。照～。光～。～斑。\n(2)显扬，显示出来夸～。炫～。～武扬威。\n(3)光荣荣～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耀"},{"id":"glyph-kai-8001","script":"kai","character":"老","reading":"lǎo","description":"lǎo：(1)年纪大，时间长，有经验，陈旧的～当益壮。～朋友。～练。～化。少年～成。～马识途。\n(2)对年纪大的人的尊称吴～。～人家。～大爷。\n(3)极，很～早。～羞成怒。\n(4)老年人敬～院。扶～携幼。～有所为（wéi）。\n(5)晚年～年。～境。\n(6)敬老，养老～吾老，以及人之老。”\n(7)总是，经常～是生病。\n(8)原来的～地方。\n(9)与嫩”相对黄瓜长～了。\n(10)词头，用于表排行，用于表相互尊称，或加在某些动植物名前构成多音节词～大。～鹰。～倭瓜。\n(11)老子（中国先秦思想家）及其学说的简称。\n(12)死的讳称～了。\n(13)姓。\n〔～板〕指业主或企业的经营者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-老"},{"id":"glyph-kai-8003","script":"kai","character":"考","reading":"kǎo","description":"kǎo：(1)试验，测验～试。～查。\n(2)检查，查核～察。～勤。稽～。～核。\n(3)推求，研究～古。～据。～订。～证。\n(4)老，年纪大寿～。\n(5)原指父亲，后多指已死的父亲先～。如丧～妣。\n(6)击，敲而陋者乃以斧斤～击而求之，自以为得其实”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-考"},{"id":"glyph-kai-8005","script":"kai","character":"者","reading":"zhě","description":"zhě：(1)用在名词、动词、形容词、数词、词组后，并与其相结合，指人、指事、指物、指时等读～。作～。二～必居其一。来～。\n(2)助词，表示语气停顿并构成判断句的句式陈胜～，阳城人也。\n(3)这，此（多用在古诗词曲中）～个。～回。～番。～边走。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-者"},{"id":"glyph-kai-800c","script":"kai","character":"而","reading":"ér","description":"ér：(1)古同尔”，代词，你或你的～翁归，自与汝复算耳”。\n(2)连词（a.表平列，如多～杂”。b.表相承，如取～代之”。c.表递进，如～且”。d.表转折，如似是～非”。e.连接肯定和否定表互为补充，如浓～不烈”。f.连接状语和中心词表修饰，如侃侃～谈”。g.插在主语谓语中间表假设，如人～无信，不知其可”）。\n(3)表（从……到……）从上～下。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-而"},{"id":"glyph-kai-800d","script":"kai","character":"耍","reading":"shuǎ","description":"shuǎ：(1)游戏玩～。～笑。\n(2)玩弄，戏弄～弄。～猴。\n(3)舞动，施展～滑。～手艺。～手腕。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耍"},{"id":"glyph-kai-8010","script":"kai","character":"耐","reading":"nai；nài","description":"nài：(1)忍，受得住忍～。～久。～人寻味。\n(2)古同奈”，奈何。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耐"},{"id":"glyph-kai-8015","script":"kai","character":"耕","reading":"gēng","description":"gēng：用犁把土翻松～种（zhòng）。～作。～耘（耕地和除草，亦泛指劳动，如着意～～，自有收获”）。笔～（喻写文章）。舌～（喻教书）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耕"},{"id":"glyph-kai-8017","script":"kai","character":"耗","reading":"hào","description":"hào：(1)减损，消费～损。～费。～资。消～。\n(2)拖延～时间。\n(3)音信，消息噩～（人死的消息）。凶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耗"},{"id":"glyph-kai-8018","script":"kai","character":"耘","reading":"yún","description":"yún：除草～田。～锄（除草和松土用的锄头）。耕～。春耕夏～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耘"},{"id":"glyph-kai-8019","script":"kai","character":"耙","reading":"pá；bà","description":"bà：(1)把土块弄碎的农具。\n(2)用耙弄碎土块这块地～两遍了。\npá：(1)聚拢谷物或平土地用的用具～子。齿～。\n(2)用耙平整土地或聚拢谷物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耙"},{"id":"glyph-kai-8033","script":"kai","character":"耳","reading":"ěr","description":"ěr：(1)听觉和平衡感觉的器官（通称耳朵”）～背（bèi）。～垂。～鬓厮磨（mó）。～穴。～聪目明。～濡目染。\n(2)像耳朵的东西木～。银～。\n(3)像耳朵一样分列两旁的东西～房。鼎～。\n(4)听说～闻。～软。～顺（指年至六十，听到别人的话，就能知道他的微妙的意思，后指人六十岁）。\n(5)文言助词，而已，罢了想当然～。\n(6)文言语气词（大致同矣”）且壮士不死则已，死即举大名～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耳"},{"id":"glyph-kai-8038","script":"kai","character":"耸","reading":"sǒng","description":"高起;矗立\n耸突出\n⒈高起，直立高～。～立。～入云霄。\n⒉惊动，震动～动。危言～听。～人听闻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耸"},{"id":"glyph-kai-803b","script":"kai","character":"耻","reading":"chǐ","description":"chǐ：羞愧，羞辱羞～。雪～。奇～大辱。～笑。～骂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耻"},{"id":"glyph-kai-803d","script":"kai","character":"耽","reading":"dān","description":"dān：(1)沉溺，入迷～乐。\n(2)迟延～误。～搁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耽"},{"id":"glyph-kai-803f","script":"kai","character":"耿","reading":"gěng","description":"gěng：(1)光明山头孤月～犹在，石上寒波晓更喧”。～～（a.光明，如～～星河”；b.形容忠诚，如忠心～～”；c.心里老想着不能忘，如～～于怀”）。\n(2)有骨气，刚正不阿～介。～直。～节（坚贞的节操）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-耿"},{"id":"glyph-kai-8042","script":"kai","character":"聂","reading":"niè","description":"假借为摄”。握持\n古代地名\n聂zhé 1.切成薄片的肉。\n聂shè 1.\"摄\"的古字。握持。 2.惧怕。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聂"},{"id":"glyph-kai-8046","script":"kai","character":"聆","reading":"líng","description":"líng：听～听。～取。～教（jiào）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聆"},{"id":"glyph-kai-804a","script":"kai","character":"聊","reading":"liáo","description":"liáo：(1)姑且，勉强，凑凑和和～且（姑且）。～以自娱。～复尔尔（姑且如此）。～备一格。\n(2)依赖，寄托无～。百无～赖。\n(3)略微～表寸心。\n(4)闲谈～天。闲～。\n(5)耳鸣～啾。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聊"},{"id":"glyph-kai-804b","script":"kai","character":"聋","reading":"lóng","description":"愚昧;不明事理","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聋"},{"id":"glyph-kai-804c","script":"kai","character":"职","reading":"zhí","description":"主管;任职\n尽职;称职\n⒈分内应做的或所担任的事情～务。～责。尽～。称～。\n⒉在工作中的位置或地位～位。～称。官～。在～。兼～。任要～。\n⒊掌管～掌。\n⒋旧时下属对上司的自称～遵命前去。\n⒌主要～由于此。\n⒍由于～此。～是之故。\n职tè 1.小木桩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-职"},{"id":"glyph-kai-8054","script":"kai","character":"联","reading":"lián","description":"⒈连结，结合～结。～合。～珠。～盟。\n⒉对子，对联贴春～。送挽～。\n，以及国际友好关系，促进经济、文化、人道主义等方面的国际合作。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-联"},{"id":"glyph-kai-8058","script":"kai","character":"聘","reading":"pìn","description":"pìn：(1)访问～问（古代指代表国家访问友邦）。通～。～使往来。\n(2)请人担任职务～书。～用。～请。招～。\n(3)定婚或女子出嫁～礼（彩礼）。～金。～姑娘。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聘"},{"id":"glyph-kai-805a","script":"kai","character":"聚","reading":"jù；jv","description":"jù：会合，集合～合。～会。～积。～集。～谈。～拢。～齐。～餐。欢～一堂。物以类～。凝～。～沙成塔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聚"},{"id":"glyph-kai-806a","script":"kai","character":"聪","reading":"cōng","description":"明察。指耳闻声音而心能辨别其是真假\n聪明,有才智\n①听觉失～。\n②听觉灵敏耳～目明。\n【聪颖】聪明机灵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-聪"},{"id":"glyph-kai-8083","script":"kai","character":"肃","reading":"sù","description":"⒈恭敬～立。～然起敬。\n⒉严正，庄重～静。严～。\n肃xiāo 1.姓氏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肃"},{"id":"glyph-kai-8086","script":"kai","character":"肆","reading":"sì","description":"sì：(1)放纵，任意行事～口。～虐。～意。放～。～无忌惮。\n(2)尽，极～力（尽力）。～目。～勤。\n(3)陈列，陈设～筵。\n(4)古代指人处死刑后暴尸示众～诸市朝。\n(5)店铺市～。茶坊酒～。\n(6)四”的大写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肆"},{"id":"glyph-kai-8087","script":"kai","character":"肇","reading":"zhào","description":"zhào：(1)开始，初始～始。～生。～端。～基（开始建立基础，打基础）。～造（开始建立）。\n(2)引发～事（a.引起事故；b.闲事）。～祸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肇"},{"id":"glyph-kai-8089","script":"kai","character":"肉","reading":"ròu","description":"ròu：(1)人或动物体内红色、柔软的组织～体。～类。～食。肌～。～票（被盗匪掳去的人，盗匪借以向他的家属勒索钱财）。～身（佛教指肉体）。\n(2)果实中可以吃的部分桂圆～。冬瓜～厚。\n(3)果实不脆，不酥～瓤西瓜。\n(4)行动迟缓，性子慢做事真～。\n(5)古代称圆形物中有孔的边。\n(6)极亲密疼爱之称，多用呼子女。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肉"},{"id":"glyph-kai-808b","script":"kai","character":"肋","reading":"lèi；lē","description":"lèi：(1)胸部的两侧两～。～骨。～膜。\n(2)像肋骨的～木。\nlē：〔～脦〕衣裳肥大，不整洁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肋"},{"id":"glyph-kai-808c","script":"kai","character":"肌","reading":"jī","description":"jī：人或动物体内附着在骨头上或构成内脏的柔软物质，由许多纤维组成（通称肌肉”）～肤。～理。心～。随意～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肌"},{"id":"glyph-kai-8096","script":"kai","character":"肖","reading":"xiāo；xiào","description":"xiāo：(1)衰微。\n(2)姓（萧”俗作肖”）。\nxiào：相似，像～像。不～。惟妙惟～。神情酷～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肖"},{"id":"glyph-kai-8098","script":"kai","character":"肘","reading":"zhǒu","description":"zhǒu：上臂与前臂相接处向外凸起的部分胳膊～儿。掣～（捉住其肘，喻阻挠别人做事）。～子（a.肘；b.指食品的猪腿上半部）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肘"},{"id":"glyph-kai-809a","script":"kai","character":"肚","reading":"dù；dǔ","description":"dù：(1)腹部，胸下腿上的部分，亦指人的肠胃部分～子。～胁。～皮。牵肠挂～（挂念，不放心）。\n(2)器物下面的中心部分炉～儿。\n(3)圆而凸起像肚子的腿～子。手指头～儿。\ndǔ：供食用的动物的胃猪～子。羊～儿。烩～丝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肚"},{"id":"glyph-kai-809b","script":"kai","character":"肛","reading":"gāng","description":"gāng：直肠末端及口儿～门。～瘘（病，直肠接近肛门处发生脓肿，形成瘘管，有的在肛门附近有开口，流脓血）。脱～（直肠或乙状结肠从肛门脱出的病）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肛"},{"id":"glyph-kai-809d","script":"kai","character":"肝","reading":"gān","description":"gān：(1)人或动物体内最大的消化腺，有合成与贮存养料、分泌胆汁、解毒等功能～脏。～炎。～胆。～肠。心～。\n(2)中医学指五脏之一～火。～气。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肝"},{"id":"glyph-kai-80a0","script":"kai","character":"肠","reading":"cháng","description":"肠子或肠子制成的食品\n内心,情怀\n【肠断】形容极度悲伤忧愁。\n【肠肥脑满】见【脑满肠肥】。\n【肠骨】见【髂骨】。\n【肠管】肠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肠"},{"id":"glyph-kai-80a1","script":"kai","character":"股","reading":"gǔ","description":"gǔ：(1)大腿，自胯至膝盖的部分～骨。～肱（亦喻左右辅助得力的人）。\n(2)事物的分支或一部分（a.资金的一份，如～份”，～东”，～票”；b.机关团体中的一个部门；c.其他，如钗～”，八～文”）。\n(3)中国古代称不等腰三角形构成直角的较长的边。\n(4)量词（a.指成条的，如七～大水”；b.指气味，如一～香味”；c.指力气，如拧成一～劲”；d.批、部分，如一小～敌军”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-股"},{"id":"glyph-kai-80a2","script":"kai","character":"肢","reading":"zhī","description":"zhī：人的手、脚、胳膊、腿的统称，亦指某些动物的四条腿四～（指两手两脚）。～体。前～◇～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肢"},{"id":"glyph-kai-80a4","script":"kai","character":"肤","reading":"fū","description":"树木、果实的表皮\n某些像皮层那样的东西\n古代用于祭祀或供食用的肉类","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肤"},{"id":"glyph-kai-80a5","script":"kai","character":"肥","reading":"féi","description":"féi：(1)含脂肪多的，与瘦”相对～肉。～胖。～缺（指收入多的官职）。～硕（a.大而肥胖；b.果实大而饱满）。～马轻裘。\n(2)土质含养分多的～沃。～美（a.肥沃；b.肥壮、丰美）。\n(3)能增加田地养分的东西（如粪、豆饼、化学配合剂等）～料。～力。\n(4)使田地增加养分～田。\n(5)指衣服鞋袜等宽大，与瘦”相对～大。～瘦儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肥"},{"id":"glyph-kai-80a9","script":"kai","character":"肩","reading":"jiān","description":"jiān：(1)脖子旁边胳膊上边的部分～膀。～胛。并～。\n(2)担负～负。～荷（hè）。～舆（轿子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肩"},{"id":"glyph-kai-80aa","script":"kai","character":"肪","reading":"fáng","description":"fáng：厚的脂膏，特指动物腰部肥厚的油脂～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肪"},{"id":"glyph-kai-80ae","script":"kai","character":"肮","reading":"āng","description":"脏;不干净\n肮脏的街道\n肮脏的池塘\n比喻卑鄙、丑恶;道义上应受指责\n肮脏的交易\n肮háng 1.咽喉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肮"},{"id":"glyph-kai-80af","script":"kai","character":"肯","reading":"kěn","description":"kěn：(1)许可，愿意首～（点头答应）。\n(2)骨头上附着的肉～綮（qīng）（筋骨结合的地方，喻重要的关键）。中（zhòng）～（喻言论正中要害）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肯"},{"id":"glyph-kai-80b2","script":"kai","character":"育","reading":"yù","description":"yù：(1)生养～龄。节～。生儿～女。\n(2)养活～婴。哺～。培～。抚～。养～。\n(3)按照一定的目的长期地教导和训练德～。智～。体～。美～。教书～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-育"},{"id":"glyph-kai-80b4","script":"kai","character":"肴","reading":"yáo","description":"yáo：做熟的鱼肉等～馔。菜～。酒～。美酒佳～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肴"},{"id":"glyph-kai-80ba","script":"kai","character":"肺","reading":"fèi","description":"fèi：人和某些高级动物的呼吸器官～脏。～病。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肺"},{"id":"glyph-kai-80be","script":"kai","character":"肾","reading":"shèn","description":"位于脊椎动物体腔内脊柱近旁的一对内脏器官,它排出尿液、尿酸和其它代谢的排泄物\n指外肾,即睾丸\n指性功能\n胃,沙囊,即肫","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肾"},{"id":"glyph-kai-80bf","script":"kai","character":"肿","reading":"zhǒng","description":"浮胀;肿胀","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-肿"},{"id":"glyph-kai-80c0","script":"kai","character":"胀","reading":"zhàng","description":"膨胀,体积变大\n⒈体积变大～大。膨～。热～冷缩。\n⒉身体内壁受到压迫而出现的不舒服感觉腹～。头～痛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胀"},{"id":"glyph-kai-80c1","script":"kai","character":"胁","reading":"xié","description":"⒈胸部的两侧，从腋下到肋骨尽处的部分两～。\n⒉恐吓，强迫威～。～迫。～制。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胁"},{"id":"glyph-kai-80c3","script":"kai","character":"胃","reading":"wèi","description":"wèi：(1)人和脊椎动物身体里主管消化食物的器官～脏。～液。～酸。～口（食欲，引申为兴趣、欲望。口”读轻声）。\n(2)星名，二十八宿之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胃"},{"id":"glyph-kai-80c6","script":"kai","character":"胆","reading":"dǎn","description":"胆子,胆量,勇气\n勇胆猛\n①胆囊。\n②胆量～大心细。\n③装在某些器物内部用来容纳水、气等的东西暖瓶～。\n【胆大妄为】毫无顾忌地胡作非为。\n【胆矾】化学式cuso4·5h2o。蓝色晶体。易溶于水，在干燥空气中会逐渐风化，脱水时变为白色。有毒。可以制电池、颜料、媒染剂、杀虫剂。又称蓝矾。\n【胆固醇】醇的一种。白色结晶，质地软。人的胆汁、神经组织、血液中含量较高。在日光的紫外线作用下可转变为维生素.。是合成性激素的重要原料。胆固醇失调会引起动\n脉硬化和胆结石病。\n【胆寒】害怕；恐惧令人～。\n【胆绿素】胆汁内所含的一种色素。\n【胆略】胆量和智谋～过人。\n【胆落心寒】形容非肠怕。\n【胆囊】浓缩和贮存胆汁的器官。多数脊椎动物的胆囊由胆管扩大而成。人的胆囊近似长梨，长在肝脏右叶的下前方。又称胆、苦胆。\n【胆怯】胆量小；害怕。\n【胆识】胆量和见识～过人。\n【胆战心惊】形容十分害怕。又作心惊胆战。\n【胆汁】肝细胞分泌的一种外分泌液。黄绿色，味苦，弱碱性。贮存在胆囊中。能促进脂肪的分解、皂化和吸收。\n【胆汁质】一种气质类型。主要特征是外向，自我控制能力弱，行为敏捷但不一定稳健。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胆"},{"id":"glyph-kai-80cc","script":"kai","character":"背","reading":"bèi；bēi","description":"bèi：(1)人体后面从肩到腰的部分～脊。～包。～影。\n(2)物体的后面或反面～面。刀～。～后。～景。\n(3)用背部对着，与向”相对～光。人心向～。\n(4)向相反的方向～地性（植物向上生长的性质）。～道而驰。\n(5)避开，离开～地。～井离乡。\n(6)凭记忆读出～书。～诵。～台词。\n(7)违反违～。～离。～信弃义。\n(8)不顺～运。～兴（xìng）。\n(9)偏僻～静。\n(10)听觉不灵耳～。\n负；\n向；腹；\nbēi：人用背驮（tuó）东西，引申为负担～负。～包。～黑锅（喻受冤枉代人受过）。～包袱（喻有沉重的思想负担或经济负担）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-背"},{"id":"glyph-kai-80ce","script":"kai","character":"胎","reading":"tāi","description":"tāi：(1)人或其他哺乳动物母体内的幼体～儿。～生。～教（jiào）（指通过母体对胎儿施加影响，为胎儿发育提供良好的条件）。胚～。怀～。\n(2)事的开始，根源祸～。\n(3)器物的粗坯泥～。铜～。\n(4)衬在衣服、被褥面子和里子之间的东西棉花～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胎"},{"id":"glyph-kai-80d6","script":"kai","character":"胖","reading":"pàng；pán；pàn","description":"pàng：人体内含脂肪多～子。肥～。\n肥；\n瘦；\npán：安泰舒适心宽体～。\n肥；\n瘦；\npàn：古代祭祀用的半体牲司马升羊右～。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-胖"}];
